import { defineConfig } from "vitest/config";

// One config for the image, at the image root, because the image is the unit CI
// addresses: `bundle-google-ci.yml`'s `unit_tests` job does `npm ci` and
// `npm test` here, and the bundle's own `build-google` stage installs from this
// same manifest.
//
// The `include` names THREE directories on purpose, and NONE is a vendored
// tree. `vendor/google-calendar-shared`, `vendor/google-docs-shared` and
// `vendor/mcp-elicitation` are copies — the first two from
// `pulsemcp/mcp-servers`, the third generated by `npm run elicitation:sync` —
// so a test written inside one of them is a merge conflict on the next
// re-vendor. The calendar copy carries one strad delta, and its test is in
// `test/` for that reason (`test/calendar-auth-mode.test.ts`). `vendor/gmail-shared` is a fork (its
// `FORK.md`), and its tests still live here rather than in it: the tree's
// tsconfig compiles everything under its `src/` into the image.
//
//   - `vendor/google-sheets-shared/test/` and `vendor/google-drive-shared/test/`
//     — neither package is vendored from anywhere; each is strad's own server,
//     written here.
//   - `test/` — the image's own source, `src/` (`src/gmail.ts` and
//     `src/docs.ts`, strad's per-account layers over the gmail and google-docs
//     trees, `src/confirm.ts`, and the `src/standalone/` entrypoints), plus the
//     gmail fork's deltas (`test/gmail-attachments.test.ts`,
//     `test/gmail-from-name.test.ts`, `test/gmail-body-text.test.ts`,
//     `test/gmail-sender-verification.test.ts`), and the calendar copy's
//     one delta (`test/calendar-auth-mode.test.ts`).
//
// The sheets and drive suites live outside each package's `include: ["src/**/*"]`, so
// `npm run build` emits exactly the `build/` it emitted before; this image's own
// tsconfig likewise includes `src/**/*` alone, so `test/` never reaches `dist/`.
export default defineConfig({
  test: {
    environment: "node",
    include: [
      "test/**/*.test.ts",
      "vendor/google-sheets-shared/test/**/*.test.ts",
      "vendor/google-drive-shared/test/**/*.test.ts",
    ],
    // The root's value, and every other tree's — `test/vitest-convergence.test.ts`
    // is what holds every config in the repo to it. The reason it is not 5s is
    // the same here as everywhere, arriving by a different route: this image is
    // NOT a leg of `ci.yml`'s `servers` matrix, it is gated by
    // `.github/workflows/bundle-google-ci.yml`, whose two jobs run on the same
    // one self-hosted box as every other workflow's — including that matrix's
    // thirteen concurrent legs. Vitest's default is a tighter bound than a
    // contended box can be held to.
    testTimeout: 20_000,
  },
});
